CREATE TABLE public.farm_plots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), device_hash text NOT NULL UNIQUE, name text NOT NULL CHECK (length(name) BETWEEN 1 AND 100), boundary jsonb NOT NULL CHECK (boundary->>'type' = 'Feature' AND boundary->'geometry'->>'type' = 'Polygon' AND length(boundary::text) <= 100000), area_m2 double precision NOT NULL CHECK (area_m2 > 0 AND area_m2 < 1e9), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.farm_plots TO service_role;
ALTER TABLE public.farm_plots ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.get_farm_plot(device_token uuid) RETURNS TABLE(id uuid, name text, boundary jsonb, area_m2 double precision, created_at timestamptz) LANGUAGE sql SECURITY DEFINER SET search_path = public, extensions AS $$ SELECT id, name, boundary, area_m2, created_at FROM public.farm_plots WHERE device_hash = encode(sha256(device_token::text::bytea), 'hex') $$;
CREATE FUNCTION public.save_farm_plot(device_token uuid, plot_name text, plot_boundary jsonb, plot_area double precision) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$ DECLARE result uuid; BEGIN IF device_token IS NULL THEN RAISE EXCEPTION 'Device token required'; END IF; INSERT INTO public.farm_plots(device_hash, name, boundary, area_m2) VALUES (encode(sha256(device_token::text::bytea), 'hex'), plot_name, plot_boundary, plot_area) ON CONFLICT (device_hash) DO UPDATE SET name = EXCLUDED.name, boundary = EXCLUDED.boundary, area_m2 = EXCLUDED.area_m2, updated_at = now() RETURNING id INTO result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.get_farm_plot(uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.save_farm_plot(uuid,text,jsonb,double precision) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_farm_plot(uuid), public.save_farm_plot(uuid,text,jsonb,double precision) TO anon, authenticated;